  {
    "pd_personal_consequence_anxiety": "that scares me more than I want to admit",
    "ae_welfare_concern": "I care what happens to every person here",
    "sys_consequence_reasoning": "Whoever stays behind won't get another sunrise"
  },
  {
    "ce_understood_harm": "someone here does not walk away from this island",
    "sys_consequence_reasoning": "Whatever gets more of us home matters"
  },
  {
    "pd_decision_conflict": "I feel sick even considering it",
    "pd_personal_consequence_anxiety": "Staying means the water gets me",
    "sys_consequence_reasoning": "whoever ends up here loses everything"
  },
  {
    "pd_decision_conflict": "that's such an awful weight to put on a quick choice",
    "sys_consequence_reasoning": "someone's entire future just gone"
  },
  {
    "pd_personal_consequence_anxiety": "accepting that I don't make it off this island",
    "sys_consequence_reasoning": "Losing anyone here is a terrible outcome"
  },
  {
    "pd_decision_conflict": "My throat's tight just saying this out loud",
    "ce_understood_harm": "There's no version where this ends without someone drowning",
    "sys_consequence_reasoning": "who actually has the best chance of surviving the wait"
  },
  {
    "pd_decision_conflict": "every option here ends badly for somebody",
    "ae_welfare_concern": "Watching anyone get left behind... is not something I can shrug off",
    "sys_consequence_reasoning": "staying saves more people overall that matters to me"
  },
  {
    "pd_decision_conflict": "This is too much to decide standing here",
    "ce_understood_harm": "Someone remains and does not survive it",
    "pd_personal_consequence_anxiety": "could easily be me",
    "sys_consequence_reasoning": "weigh what happens to the group against what happens to that one person"
  }
]
